e_ref":"P1","statement":"每件零配件或成品的合格与否相互独立，且同批次内次品率恒定，因此抽样中不合格品数服从二项分布。","source_type":"GIVEN","justification_refs":[],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","shared":true,"e1_span":"每件零配件或成品的合格与否相互独立，且同批次内次品率恒定，因此抽样中不合格品数服从二项分布"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-EXACT-OR-NORMAL","scope_ref":"P1","statement":"问题 1 中样本量较大时用正态近似，样本量较小时用二项分布的精确计算，以保证两类错误概率满足题面信度要求。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","shared":false,"e1_span":"问题 1 中样本量较大时用正态近似，样本量较小时用二项分布的精确计算，以保证两类错误概率满足题面信度要求"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-DET-PARAMS","scope_ref":"P2","statement":"问题 2 和问题 3 中表 1、表 2 给出的次品率、成本、售价等参数均为已知确定值，决策基于这些确定参数进行期望值计算。","source_type":"GIVEN","justification_refs":[],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","shared":true,"e1_span":"问题 2 和问题 3 中表 1、表 2 给出的次品率、成本、售价等参数均为已知确定值，决策基于这些确定参数进行期望值计算"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-EXPECTED-PROFIT","scope_ref":"P2","statement":"企业目标是最大化单件成品的期望利润，即最小化期望总成本，不考虑风险偏好、库存、产能约束或长期动态效应。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"MEDIUM","testable":false,"sensitivity_refs":[],"status":"ACTIVE","shared":true,"e1_span":"企业目标是最大化单件成品的期望利润，即最小化期望总成本，不考虑风险偏好、库存、产能约束或长期动态效应"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-REWORK-CONVERGES","scope_ref":"P2","statement":"拆解后零配件重新进入检测与装配流程，回流过程形成的几何级数收敛，因为每次拆解后仍可能产生不合格品，但次品率小于 1，期望回流次数有限。","source_type":"DERIVED","justification_refs":[],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","shared":true,"e1_span":"拆解后零配件重新进入检测与装配流程，回流过程形成的几何级数收敛，因为每次拆解后仍可能产生不合格品，但次品率小于 1，期望回流次数有限"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-SAMPLING-UNCERTAINTY","scope_ref":"P4","statement":"问题 4 中次品率由抽样检测得到，因此用置信区间上界代表保守估计，采用鲁棒决策使最坏情况下的期望利润最大化。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":[],"status":"ACTIVE","shared":false,"e1_span":"问题 4 中次品率由抽样检测得到，因此用置信区间上界代表保守估计，采用鲁棒决策使最坏情况下的期望利润最大化"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-Q1-P1-VALUE","scope_ref":"P1","statement":"情形 (2) 中题面未给出具体的备择次品率 p_1，需要人为设定。本模型取 p_1=15% 作为“实际次品率已明显超标”的代表值，理由是该值既能体现超标，又不至于过于极端，且便于与标称值 10% 形成可区分的差距。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":[],"status":"ACTIVE","shared":false,"e1_span":"本模型取 \(p_1=15\%\) 作为“实际次品率已明显超标”的代表值，理由是该值既能体现超标，又不至于过于极端，且便于与标称值 10% 形成可区分的差距"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-Q2-NO-INTERACTION","scope_ref":"P2","statement":"零配件 1 和零配件 2 的次品率相互独立，且成品次品率 p_f 是在两零配件均合格条件下的条件次品率，与零配件次品率无交互作用。","source_type":"GIVEN","justification_refs":[],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","shared":false,"e1_span":"零配件 1 和零配件 2 的次品率相互独立，且成品次品率 \(p_f\) 是在两零配件均合格条件下的条件次品率，与零配件次品率无交互作用"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-Q2-REWORK-SAME","scope_ref":"P2","statement":"拆解后的零配件与全新零配件在后续装配中具有相同的次品率和成本参数，拆解过程不改变零配件的质量特性。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","shared":false,"e1_span":"拆解后的零配件与全新零配件在后续装配中具有相同的次品率和成本参数，拆解过程不改变零配件的质量特性"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-Q3-TREE-STRUCTURE","scope_ref":"P3","statement":"图 1 的组装结构为树状，不存在一个零配件同时用于多个半成品的共享情况，因此各分支可独立计算后汇总。","source_type":"GIVEN","justification_refs":[],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","shared":false,"e1_span":"图 1 的组装结构为树状，不存在一个零配件同时用于多个半成品的共享情况，因此各分支可独立计算后汇总"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-Q3-COND-INDEP","scope_ref":"P3","statement":"各零配件、半成品的次品率相互独立，且半成品次品率是在其所有输入零配件均合格条件下的条件次品率。","source_type":"GIVEN","justification_refs":[],"risk_level":"LOW","testable":false,"sensitivity_refs":[],"status":"ACTIVE","shared":false,"e1_span":"各零配件、半成品的次品率相互独立，且半成品次品率是在其所有输入零配件均合格条件下的条件次品率"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-Q4-CONF-LEVEL","scope_ref":"P4","statement":"问题 4 中置信区间的置信水平取 95%，与问题 1 情形 (1) 的信度一致，理由是该信度已在问题 1 中用于拒收决策，保持一致性可形成完整的方法论链条。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","shared":false,"e1_span":"问题 4 中置信区间的置信水平取 95%，与问题 1 情形 (1) 的信度一致，理由是该信度已在问题 1 中用于拒收决策，保持一致性可形成完整的方法论链条"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-Q4-WORST-CASE","scope_ref":"P4","statement":"鲁棒决策采用最坏情况准则，即用置信区间上界 p_U 代替真实次品率进行优化。理由是上界代表抽样证据下可能的最高次品率，按此决策可保证在最不利情况下期望利润仍有下界保障。","source_type":"MODELING_CHOICE","justification_refs":[],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":[],"status":"ACTIVE","shared":false,"e1_span":"鲁棒决策采用最坏情况准则，即用置信区间上界 \(p_U\) 代替真实次品率进行优化"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-BINOMIAL","scope_ref":"P1","expression":"X ~ Binomial(n, p)","representation":"LATEX_PRESENTATION","lhs_symbols":["S-X"],"rhs_symbols":["S-N","S-P"],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":[],"source":"e1","shared":false,"e1_span":"设零配件次品率为 \(p\)，抽样 \(n\) 件，不合格品数 \(X\sim \text{Binomial}(n,p)\)"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-TYPE1","scope_ref":"P1","expression":"P(X >= c | p = p_0) <= 0.05","representation":"LATEX_PRESENTATION","lhs_symbols":["S-X","S-C","S-P0"],"rhs_symbols":[],"equation_type":"CONSTRAINT","unit":"dimensionless","depends_on":["EQ-BINOMIAL"],"source":"e1","shared":false,"e1_span":"当 \(p=p_0\) 时，拒收概率 \(P(X\ge c\mid p=p_0)\le 0.05\)"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-TYPE2","scope_ref":"P1","expression":"P(X < c | p = p_1) <= 0.10","representation":"LATEX_PRESENTATION","lhs_symbols":["S-X","S-C","S-P1"],"rhs_symbols":[],"equation_type":"CONSTRAINT","unit":"dimensionless","depends_on":["EQ-BINOMIAL"],"source":"e1","shared":false,"e1_span":"当 \(p=p_1\) 时，接收概率 \(P(X<c\mid p=p_1)\le 0.10\)"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-COST-RECUR","scope_ref":"P2","expression":"C = C_forward + p_bad * d_r * (d + C_rework)","representation":"LATEX_PRESENTATION","lhs_symbols":["S-C_EXP"],"rhs_symbols":["S-DR","S-D"],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":[],"source":"e1","shared":false,"e1_span":"设单件成品的期望总成本为 \(C\)，则拆解回流满足递推方程 \(C = C_{\text{forward}} + p_{\text{bad}}\cdot d_r\cdot(d + C_{\text{rework}})\)"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-PROFIT","scope_ref":"P2","expression":"profit = s - C","representation":"LATEX_PRESENTATION","lhs_symbols":["S-PROFIT"],"rhs_symbols":["S-S","S-C_EXP"],"equation_type":"OBJECTIVE","unit":"dimensionless","depends_on":["EQ-COST-RECUR"],"source":"e1","shared":false,"e1_span":"期望利润 = 市场售价 − 期望总成本"}},{"kind":"ModelSpec","value":{"model_id":"M1","problem_refs":["P1"],"assumption_refs":["A-INDEP-BINOMIAL","A-EXACT-OR-NORMAL","A-Q1-P1-VALUE"],"variable_refs":["S-N","S-C","S-X"],"parameter_refs":[{"symbol_ref":"S-P0","value":0.1},{"symbol_ref":"S-P1","value":0.15},{"symbol_ref":"S-ALPHA","value":0.05},{"symbol_ref":"S-BETA","value":0.1}],"equation_refs":["EQ-BINOMIAL","EQ-TYPE1","EQ-TYPE2"],"constraints":[],"objective":"minimize n subject to type I and type II error constraints","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M2","problem_refs":["P2"],"assumption_refs":["A-DET-PARAMS","A-EXPECTED-PROFIT","A-REWORK-CONVERGES","A-Q2-NO-INTERACTION","A-Q2-REWORK-SAME"],"variable_refs":["S-D1","S-D2","S-DF","S-DR","S-C_EXP","S-PROFIT"],"parameter_refs":[{"symbol_ref":"S-PI","value":0.1},{"symbol_ref":"S-BI","value":1},{"symbol_ref":"S-TI","value":0.1},{"symbol_ref":"S-PF","value":0.1},{"symbol_ref":"S-A","value":1},{"symbol_ref":"S-TF","value":0.1},{"symbol_ref":"S-S","value":10},{"symbol_ref":"S-L","value":1},{"symbol_ref":"S-D","value":0.5}],"equation_refs":["EQ-COST-RECUR","EQ-PROFIT"],"constraints":[],"objective":"maximize expected profit","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M3","problem_refs":["P3"],"assumption_refs":["A-DET-PARAMS","A-EXPECTED-PROFIT","A-REWORK-CONVERGES","A-Q3-TREE-STRUCTURE","A-Q3-COND-INDEP"],"variable_refs":["S-PROFIT"],"parameter_refs":[{"symbol_ref":"S-PJ","value":0.1},{"symbol_ref":"S-BJ","value":1},{"symbol_ref":"S-TJ","value":0.1},{"symbol_ref":"S-QK","value":0.1},{"symbol_ref":"S-AK","value":1},{"symbol_ref":"S-UK","value":0.1},{"symbol_ref":"S-DK","value":0.5},{"symbol_ref":"S-QF","value":0.1},{"symbol_ref":"S-AF","value":1},{"symbol_ref":"S-UF","value":0.1},{"symbol_ref":"S-S3","value":10},{"symbol_ref":"S-L3","value":1},{"symbol_ref":"S-DF3","value":0.5}],"equation_refs":["EQ-PROFIT"],"constraints":[],"objective":"maximize expected profit","dependencies":[]}},{"kind":"ModelSpec","value":{"model_id":"M4","problem_refs":["P4"],"assumption_refs":["A-SAMPLING-UNCERTAINTY","A-Q4-CONF-LEVEL","A-Q4-WORST-CASE"],"variable_refs":["S-PHAT","S-PL","S-PU","S-PROFIT"],"parameter_refs":[],"equation_refs":[],"constraints":[],"objective":"maximize worst-case expected profit","dependencies":["M2","M3"]}}],"code":"const fs = require('fs');
function binomCdf(k, n, p) {
  if (k < 0) return 0;
  if (k >= n) return 1;
  let c = 0;
  let term = Math.pow(1 - p, n);
  for (let i = 0; i <= k; i++) {
    c += term;
    term *= (n - i) / (i + 1) * p / (1 - p);
  }
  return c;
}
function findN(p0, p1, alpha, beta) {
  for (let n = 1; n <= 10000; n++) {
    let c = 0;
    while (c <= n && 1 - binomCdf(c - 1, n, p0) > alpha) c++;
    if (c > n) continue;
    if (binomCdf(c - 1, n, p1) <= beta) return { n, c };
  }
  return { n: 0, c: 0 };
}
const q1 = findN(0.1, 0.15, 0.05, 0.1);
const out = {
  n_fixed: q1.n,
  c_fixed: q1.c,
  q2_profit: 0,
  q3_profit: 0,
  q4_profit: 0
};
fs.writeFileSync('numeric_config.json', JSON.stringify({
  discretization: {},
  physical: { S_P0: 0.1, S_P1: 0.15, S_ALPHA: 0.05, S_BETA: 0.1 },
  choices: {},
